<?php
namespace Tests\Feature;use App\Models\Admin;use App\Models\Employee;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class SupervisorScopeTest extends TestCase {use RefreshDatabase;public function test_supervisor_can_read_direct_report_but_not_unrelated_employee():void{$lead=Employee::create(['employee_id'=>'LEAD','nik'=>'N1','name'=>'Lead','department'=>'Ops']);$report=Employee::create(['employee_id'=>'REP','nik'=>'N2','name'=>'Report','department'=>'Ops','supervisor_id'=>$lead->id]);$other=Employee::create(['employee_id'=>'OTHER','nik'=>'N3','name'=>'Other','department'=>'Ops']);$admin=Admin::create(['name'=>'Supervisor','email'=>'supervisor@test.local','password'=>bcrypt('p'),'role'=>'supervisor','employee_id'=>$lead->id]);Sanctum::actingAs($admin);$this->getJson('/api/v1/user-management/employees/'.$report->id.'/360')->assertOk();$this->getJson('/api/v1/user-management/employees/'.$other->id.'/360')->assertForbidden();}}
